import{_ as a,o as e,c as i,ae as t}from"./chunks/framework.Dn6zxbF8.js";const k=JSON.parse('{"title":"Walkthrough: one service from pull request to production","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/6497710059/references/walkthrough.md","filePath":"adrs/6497710059/references/walkthrough.md"}'),h={name:"adrs/6497710059/references/walkthrough.md"};function n(o,s,l,p,r,c){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="walkthrough-one-service-from-pull-request-to-production" tabindex="-1">Walkthrough: one service from pull request to production <a class="header-anchor" href="#walkthrough-one-service-from-pull-request-to-production" aria-label="Permalink to &quot;Walkthrough: one service from pull request to production&quot;">​</a></h1><p>This follows the <code>api</code> service of the <code>shop</code> repository, owned by <code>acme</code> on GitHub Container Registry, from a pull request to a release. <code>&lt;commit&gt;</code> stands for the full 40-character commit SHA, <code>3f2c…4e3f</code> here, and the namespace is <code>shop</code>.</p><h2 id="pull-request" tabindex="-1">Pull request <a class="header-anchor" href="#pull-request" aria-label="Permalink to &quot;Pull request&quot;">​</a></h2><p>Commit <code>3f2c…4e3f</code> is pushed to a pull request branch. The build publishes a multi-platform image and a prerelease chart, both marked <code>pr-</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> buildx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux/amd64,linux/arm64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --annotation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;index:org.opencontainers.image.source=https://github.com/acme/shop&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --annotation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;index:org.opencontainers.image.revision=3f2c…4e3f&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/acme/images/shop/api:pr-3f2c…4e3f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devops/helm/charts/api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0-pr-3f2c…4e3f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --app-version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pr-3f2c…4e3f</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-0.0.0-pr-3f2c…4e3f.tgz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oci://ghcr.io/acme/charts/shop</span></span></code></pre></div><p>Helm appends the chart name, so the chart lands at <code>ghcr.io/acme/charts/shop/api:0.0.0-pr-3f2c…4e3f</code>.</p><h2 id="default-branch" tabindex="-1">Default branch <a class="header-anchor" href="#default-branch" aria-label="Permalink to &quot;Default branch&quot;">​</a></h2><p>The pull request merges with a fast-forward, so <code>main</code> builds the same commit and publishes it without the <code>pr-</code> mark, as <code>images/shop/api:3f2c…4e3f</code> and <code>charts/shop/api:0.0.0-sha-3f2c…4e3f</code>, whose default image is that same commit. A squash or merge commit gets its own SHA and tags the same way. The pull request tags stay where they are and expire later.</p><h2 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h2><p>The git tag <code>v1.4.0</code> is pushed on that commit. The image is not built again; the release adds the version to the image the default branch built, so the digest stays the same:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/acme/images/shop/api:3f2c…4e3f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.4.0</span></span></code></pre></div><p>The chart does not follow the image. Its version is the <code>version</code> in its <code>Chart.yaml</code>, <code>2.1.0</code> here, which changed because the chart did, and a chart release is cut when the chart changes, not when the image does. Its <code>appVersion</code> and image tag default are set to <code>1.4.0</code> in that change, so the chart deploys this release unless a user overrides the image. It is pushed as <code>charts/shop/api:2.1.0</code>. Helm requires the tag to equal the chart version, so the commit is read from its <code>org.opencontainers.image.revision</code> annotation. An image release that leaves the chart as it is, such as <code>1.4.1</code>, publishes no chart.</p><p>With <code>docker/metadata-action</code>, the same tag names come from:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docker/metadata-action@v5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    images</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ghcr.io/acme/images/shop/api</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      type=semver,pattern={{version}}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      type=sha,format=long,prefix=</span></span></code></pre></div><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>A deployment pins the release by tag and digest:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ghcr.io/acme/images/shop/api:1.4.0@sha256:9b1e…</span></span></code></pre></div><p>The cluster pulls the digest. A reader sees the release, and <code>crane ls ghcr.io/acme/images/shop/api</code> lists <code>3f2c…4e3f</code> next to <code>1.4.0</code>, which leads back to the commit in git.</p><h2 id="variant" tabindex="-1">Variant <a class="header-anchor" href="#variant" aria-label="Permalink to &quot;Variant&quot;">​</a></h2><p>A debug build of the same release is <code>images/shop/api:1.4.0-debug</code>, a suffix on the tag rather than another image name.</p><h2 id="moving-tags-for-images-others-pull" tabindex="-1">Moving tags for images others pull <a class="header-anchor" href="#moving-tags-for-images-others-pull" aria-label="Permalink to &quot;Moving tags for images others pull&quot;">​</a></h2><p>If <code>api</code> were an open source image, the release would also move these tags:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/acme/images/shop/api:1.4.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/acme/images/shop/api:1.4.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1.x</span></span></code></pre></div><p>An image only we deploy never gets them.</p><h2 id="wasm-component" tabindex="-1">Wasm component <a class="header-anchor" href="#wasm-component" aria-label="Permalink to &quot;Wasm component&quot;">​</a></h2><p>The WIT package <code>acme:greeter</code> at <code>0.3.0</code> publishes to <code>ghcr.io/acme/wasm-components/acme/greeter:0.3.0</code>.</p><h2 id="mirror" tabindex="-1">Mirror <a class="header-anchor" href="#mirror" aria-label="Permalink to &quot;Mirror&quot;">​</a></h2><p>Postgres is copied from Docker Hub with its upstream path and tag:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker.io/library/postgres:16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/acme/mirrors/docker-hub/library/postgres:16</span></span></code></pre></div><p>The <code>16</code> tag follows the upstream on every refresh. In Artifact Registry the same image is <code>&lt;location&gt;-docker.pkg.dev/&lt;project&gt;/mirrors-docker-hub/library/postgres:16</code>.</p><h2 id="signatures" tabindex="-1">Signatures <a class="header-anchor" href="#signatures" aria-label="Permalink to &quot;Signatures&quot;">​</a></h2><p><code>cosign sign ghcr.io/acme/images/shop/api@sha256:9b1e…</code> stores the signature in <code>images/shop/api</code>, attached to the digest. <code>oras copy -r</code> moves it along with the image to another registry; a plain pull and push leaves it behind.</p><h2 id="cleanup" tabindex="-1">Cleanup <a class="header-anchor" href="#cleanup" aria-label="Permalink to &quot;Cleanup&quot;">​</a></h2><p>A scheduled job deletes <code>pr-*</code> and <code>0.0.0-pr-*</code> versions after the age the project sets, since GitHub Container Registry has no cleanup policy. Nothing tagged <code>1.4.0</code> is deleted.</p><h2 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ghcr.io/acme</span></span>
<span class="line"><span>├── images/shop/api                     1.4.0, 1.4.0-debug, 3f2c…4e3f, latest, 1.x</span></span>
<span class="line"><span>├── charts/shop/api                     2.1.0, 0.0.0-sha-3f2c…4e3f</span></span>
<span class="line"><span>├── wasm-components/acme/greeter        0.3.0</span></span>
<span class="line"><span>└── mirrors/docker-hub/library/postgres 16</span></span></code></pre></div>`,36)])])}const g=a(h,[["render",n]]);export{k as __pageData,g as default};
